insert into public.posts (id,thread_id,author_handle,body,quote_post_id,created_at) values
  (1901,19,'staff','Welcome. Be civil, no posting about players'' families, no screenshots of premium posts. The Paddock and Film Room Lounge are members-only; everything else is free. Every username and post on this demo board is fictional.',null,now()-interval '30240 minutes'),
  (1902,19,'cox','Appreciate the no-screenshots rule. Keeps the good info coming.',null,now()-interval '20160 minutes'),
  (101,1,'staff','Closed practice, but here''s what I can share. The WR rotation looked different in team periods: the junior slot took most of the first-team reps and the true freshman got real run on the outside. Defensive line was healthy and loud. More in Thursday''s report.',null,now()-interval '38 minutes'),
  (102,1,'pete','Freshman getting first-team reps in late October tells you everything. This is why I pay for the Red & Blue tier.',101,now()-interval '34 minutes'),
  (103,1,'hank','Any word on the kicking battle? Last week was rough to watch from the south end zone.',null,now()-interval '30 minutes'),
  (104,1,'staff','Kicker looked sharp from distance in the period I watched. I wouldn''t read too much into one practice.',103,now()-interval '25 minutes'),
  (105,1,'ford','Good to hear. I was sitting right behind the uprights for the miss and the groan from our section was audible in Snider Plaza.',104,now()-interval '21 minutes'),
  (106,1,'grace','Love the detail. Can we get a film breakdown of the 3rd-and-long package on the Paddock Report?',null,now()-interval '17 minutes'),
  (107,1,'dre','Already cut it up. It''s going in the Film Room Lounge tomorrow morning.',106,now()-interval '13 minutes'),
  (108,1,'peruna','Dre with the assist. Somebody get this man a corny dog.',107,now()-interval '8 minutes'),
  (201,2,'mike','Kickoff is 11 a.m. CT Saturday in Syracuse, on ESPN2. Drop your score predictions and keep it civil. Pony Up!',null,now()-interval '120 minutes'),
  (202,2,'dallas','34-17 Mustangs. Defense gets two picks.',null,now()-interval '108 minutes'),
  (203,2,'ray','31-24. Too many people sleeping on their run game.',202,now()-interval '96 minutes'),
  (204,2,'belle','Watch party is at our usual spot off Lovers Lane. Red and blue cookies again this week.',null,now()-interval '84 minutes'),
  (205,2,'band','Anybody making the trip? A few of us band alumni fly into Syracuse Friday night and would love company in the visitors section.',null,now()-interval '72 minutes'),
  (206,2,'snider','First road game as a member. Is the 11 a.m. kick Dallas time or Syracuse time?',null,now()-interval '60 minutes'),
  (207,2,'peruna','11 a.m. Central, noon in Syracuse. Set an alarm and get the queso going early.',206,now()-interval '48 minutes'),
  (208,2,'hank','Bold call: if they run it like they did against Cal, this one is decided by halftime.',null,now()-interval '36 minutes'),
  (209,2,'ray','Hank stealing my take. I''m sticking with 31-24.',203,now()-interval '24 minutes'),
  (301,3,'staff','Big visit weekend for the hoops staff. Both guards (fictional, for this demo) sat courtside for the scrimmage and met with the Cox business school. Early read: very positive.',null,now()-interval '300 minutes'),
  (302,3,'ray','Whoever runs the visit itinerary deserves a raise.',null,now()-interval '225 minutes'),
  (303,3,'hank','NIL matters here. Fan support through SMU’s official programs could move the needle.',null,now()-interval '150 minutes'),
  (401,4,'grace','Three goals in Berkeley on Thursday. Two left: at North Carolina on Oct. 29, then Pitt at Washburne on Nov. 5. Thinking of organizing an SMU+ meetup for Pitt.',null,now()-interval '4320 minutes'),
  (402,4,'belle','Count me in. The Red & Blue tier invite included a watch party for the UNC match too.',null,now()-interval '3240 minutes'),
  (403,4,'cox','Tough ACC stretch, but that win at Cal was fun to watch.',null,now()-interval '2160 minutes'),
  (501,5,'belle','If you have not watched the Mic''d Up episode, go now. Hearing the setter call the rotation change in real time was wild.',null,now()-interval '540 minutes'),
  (502,5,'pete','This is the content that makes the membership worth it. More of this, please.',null,now()-interval '360 minutes'),
  (601,6,'ray','PG, two wings, stretch four and the big transfer. Defense first. Thoughts?',null,now()-interval '660 minutes'),
  (602,6,'dallas','You are underrating the freshman. He will start by January.',null,now()-interval '495 minutes'),
  (603,6,'hank','Depth is the question. Love the top six though.',null,now()-interval '330 minutes'),
  (701,7,'belle','Brisket is a given. What else? Last time the queso disappeared in 10 minutes.',null,now()-interval '1440 minutes'),
  (702,7,'mike','Smoked wings and a big tub of banana pudding. Never fails.',null,now()-interval '1080 minutes'),
  (703,7,'cox','Breakfast tacos for the early kickoffs. Trust me.',null,now()-interval '720 minutes'),
  (801,8,'staff','Spent the morning on deck. The distance group is ahead of last year''s splits. The diving coach thinks a fictional sophomore has a real shot at the podium.',null,now()-interval '1440 minutes'),
  (802,8,'grace','Didn''t know I cared about swim until SMU+. Now I''m hooked.',null,now()-interval '960 minutes'),
  (901,9,'staff','Pinned. How the proposed model works: 40% of membership revenue would go to SMU Athletics’ official NIL and revenue-sharing programs, with athlete deals disclosed through the NIL Go clearinghouse. SMU+ would not pick or pay individual athletes or teams. (Sample post for this concept.)',null,now()-interval '2880 minutes'),
  (902,9,'cox','Clear rules like this are why I joined.',null,now()-interval '2160 minutes'),
  (903,9,'hank','Good that it runs through SMU’s official programs.',null,now()-interval '1440 minutes'),
  (1001,10,'staff','Updated tracker. All prospects referenced on this demo board are fictional.',null,now()-interval '2880 minutes'),
  (1002,10,'ray','The DL haul is going to be special.',null,now()-interval '1920 minutes'),
  (1101,11,'cox','Fifth of 18 in Wilmington, after a T4th in Seattle and a T5th at Haskins. Solid fall.',null,now()-interval '300 minutes'),
  (1102,11,'pete','The swing breakdown video on SMU+ was great.',null,now()-interval '200 minutes'),
  (1201,12,'mike','Mine: picture-in-picture for live Q&As, and a dark mode.',null,now()-interval '5760 minutes'),
  (1202,12,'grace','Push alerts when an athlete I follow posts.',null,now()-interval '3840 minutes'),
  (1301,13,'grace','Two team wins in September (John McKenzie and the Texas A&M Invitational). ACCs are Oct. 30 in Blacksburg. Who is watching?',null,now()-interval '5760 minutes'),
  (1401,14,'staff','The new full-court press is aggressive. Here is how it works and why the staff thinks it fits this roster.',null,now()-interval '7200 minutes'),
  (1402,14,'belle','Loved the telestrator clips.',null,now()-interval '4800 minutes'),
  (1501,15,'hank','Great to see SMU racing in Cambridge. Next up is Texas at White Rock Lake on Nov. 8.',null,now()-interval '8640 minutes'),
  (1601,16,'ray','Fall is all individual events. Who is going to the ITA Sectionals Nov. 5-8? Dual season starts in the spring.',null,now()-interval '10080 minutes'),
  (1701,17,'belle','Georgia at the Dallas Equestrian Center on Nov. 6, then Oklahoma State on Nov. 7. Highly recommend, the riders are incredible.',null,now()-interval '10080 minutes'),
  (1801,18,'dallas','Unbeaten through 14. Louisville at Washburne on Oct. 30, 6:30 p.m. on ACCN. Pack it out.',null,now()-interval '10080 minutes'),
  (2001,20,'dre','Cut up the A-gap sim pressure snap by snap. Watch the boundary linebacker: he always shows blitz and only sometimes comes. QB sees six, gets four.',null,now()-interval '240 minutes'),
  (2002,20,'ray','The free safety not moving until the snap is so disciplined. You can see the QB staring at him.',2001,now()-interval '200 minutes'),
  (2003,20,'peruna','Is this sustainable? Feels like good offenses will motion the back out and stress it.',null,now()-interval '160 minutes'),
  (2004,20,'dre','Exactly the counter. Staff has an answer, but I''ll save it for Thursday.',2003,now()-interval '120 minutes'),
  (2005,20,'grace','This is the best thing on the site. Worth the membership by itself.',null,now()-interval '80 minutes'),
  (2101,21,'jt','Current list: one official, three unofficial. The QB is back for a third trip. All names on this demo board are fictional.',null,now()-interval '420 minutes'),
  (2102,21,'ford','Third visit is the one that matters. Friday night under the lights at Ford should help.',2101,now()-interval '336 minutes'),
  (2103,21,'hank','Any OL on the list? That''s the need.',null,now()-interval '252 minutes'),
  (2104,21,'jt','One tackle from East Texas, unofficial. Staff likes him a lot.',2103,now()-interval '168 minutes'),
  (2201,22,'band','Fifteen years out of the band and that show still gave me chills. Anyone get the full thing from the west side?',null,now()-interval '1440 minutes'),
  (2202,22,'belle','Got most of it. Uploading tonight.',null,now()-interval '1080 minutes'),
  (2203,22,'snider','The drumline feature at the end. Wow.',2201,now()-interval '720 minutes');
insert into public.content_items (id,type,category,label,title,description,duration,members_only,sport,sort) values
  ('smu-fb-cal-highlights','video','watch','Football · Official highlights','SMU Football: Highlights vs. Cal','Down 20-17 at the half, then 42 unanswered. Official highlights from the 59-20 win at Ford Stadium, Oct. 24.','7:59',false,'football',0),
  ('smu-fb-uva-highlights','video','watch','Football · Official highlights','SMU Football: Highlights vs. Virginia','The 23-13 win over Virginia on Oct. 17, the day Kendrick Raphael ran for 119.','8:00',false,'football',1),
  ('smu-msoc-cal-highlights','video','watch','Men''s Soccer · Official highlights','SMU Men''s Soccer: Highlights at Cal','Berkeley, Oct. 24: a 2-0 win, the tenth clean sheet of an unbeaten season.','4:00',false,'mens-soccer',2),
  ('smu-vb-gt-highlights','video','watch','Volleyball · Official highlights','SMU Volleyball: Highlights at Georgia Tech','Atlanta, Oct. 25. Straight sets, the second road sweep in three days.','6:16',false,'volleyball',3),
  ('smu-vb-clemson-highlights','video','watch','Volleyball · Official highlights','SMU Volleyball: Highlights at Clemson','Oct. 23: the first of two straight-set road wins that week.','5:16',false,'volleyball',4),
  ('smu-msoc-uca-highlights','video','watch','Men''s Soccer · Official highlights','SMU Men''s Soccer: Highlights vs. Central Arkansas','Oct. 20 at Washburne: a 5-2 win with a Stephan Soghomonian hat trick.','5:00',false,'mens-soccer',5),
  ('smu-msoc-duke-highlights','video','watch','Men''s Soccer · Official highlights','SMU Men''s Soccer: Highlights vs. Duke','Oct. 10 at Washburne: six goals against Duke.','7:00',false,'mens-soccer',6),
  ('smu-texas-capital-video','video','watch','SMU Athletics · Announcement','SMU Athletics: The Texas Capital jersey patch','The 38-second official unveiling of the all-sports patch.','0:38',false,'general',7),
  ('smu-wsoc-uva-presser','video','watch','Women''s Soccer · Postgame','SMU Women''s Soccer: Postgame press conference vs. Virginia','After the Oct. 11 match against Virginia.','4:01',false,'womens-soccer',8),
  ('smu-mbb-tipoff-players','video','watch','Men''s Basketball · ACC Tipoff','SMU Men''s Basketball: Rowan Brumbaugh and Jaden Toombs at ACC Tipoff','Two Mustangs, live at the ACC''s preseason media event.','5:44',false,'mens-basketball',9),
  ('boulevard-nights-1','video','watch','Gameday · The Boulevard','The Boulevard on The ACC Huddle','SMU''s tailgate on the Boulevard, as the ACC Huddle saw it. An official SMU Athletics video.','3:06',false,'football',10),
  ('boulevard-nights-2','video','watch','Sample · Docuseries · Ep. 2','Boulevard Nights: Band Day','Three hundred instruments, one halftime show and a drumline that practices in the parking garage. (Fictional sample.)','19:12',true,null,11),
  ('smu-fb-avail-0814','video','watch','Football · Fall camp','SMU Football: Fall camp media availability','From fall camp, Aug. 14: SMU Football''s media availability with Coach Thibodeaux, J. Jefferson and M. Alcorn-Crowder.','10:27',true,'football',12),
  ('smu-fb-avail-1020','video','watch','Football · Game week','SMU Football: Rhett Lashlee and Kevin Jennings, game-week media availability','The head coach and the quarterback, on the Monday before the Cal game (Oct. 20).','11:55',true,'football',13),
  ('smu-swim-classic','article','insider','Swimming & Diving · Meet recap','A record tied after 28 years, and two Mustang podiums','At the SMU Classic, Maddy Parker matched a 100 free school record set in 1997-98. Both SMU teams finished third.','2 min read',false,'swimming-diving',14),
  ('smu-mbb-enfield-tipoff','video','watch','Men''s Basketball · ACC Tipoff','SMU Men''s Basketball: Andy Enfield at ACC Tipoff','The head coach, live at the ACC''s preseason media event.','4:15',true,'mens-basketball',15),
  ('preview-syracuse','article','insider','Game Preview','SMU at Syracuse: one trip north, then back to the lights','Four straight wins, a 42-0 second half in the rearview and the only road date in a seven-week stretch. Sat., 11 a.m. CT, ESPN2.','4 min read',false,null,16),
  ('preview-msoc-louisville','article','insider','Men''s Soccer · Preview','Fourteen games, no losses: men''s soccer hosts Louisville','Ten clean sheets, 41 goals and a Friday night on ACC Network. The unbeaten Mustangs come home to Washburne.','3 min read',false,null,17),
  ('vb-road-sweep','article','insider','Volleyball','Six sets, zero dropped: volleyball sweeps its way out of a rough week','Two home losses, then straight-set wins at Clemson and Georgia Tech. Two more road matches, then four straight at Moody.','3 min read',false,null,18),
  ('recap-cal','article','insider','Recap','Forty-two unanswered: how SMU turned a halftime deficit into 59-20','Down 20-17 at the break, the Mustangs scored on six straight drives and Kevin Jennings took the school record for touchdown passes.','4 min read',false,null,19),
  ('feature-raphael','article','insider','Player Feature','Same opponent, other sideline: Kendrick Raphael''s full circle','Last November his late touchdown beat SMU. On Saturday he scored three for the Mustangs against the team he left.','4 min read',false,null,20),
  ('feature-jennings-record','article','insider','Player Feature','Seventy-four: Kevin Jennings and the record Oak Cliff built','Twenty-two passes as a freshman. Now the most touchdown passes in SMU history. Five seasons, by the numbers.','4 min read',false,null,21),
  ('smu-weekend-oct24','article','insider','Insider · Weekend roundup','No. 19, a first ACC title, and a fifth in the wind','Football climbs to No. 19 in the AP poll, men''s soccer clinches a share of the program''s first ACC regular-season title, and women''s golf finishes fifth at the Landfall Tradition.','3 min read',false,'general',22),
  ('smu-rowing-charles','article','insider','Rowing · Race recap','Bronze on the Charles','SMU opened its fall at the Head of the Charles with a third-place medal in the women''s club fours.','2 min read',false,'rowing',23),
  ('walk-on','article','insider','Sample · Feature','From walk-on to Saturday starter','Four years, no scholarship, and a locker next to the laundry room. (Fictional sample.)','8 min read',false,null,24),
  ('smu-business-october','article','insider','Insider · Business of SMU Athletics','A patch on every jersey, and Texas''s first D-I men''s lacrosse team','Two October announcements, one week apart: Texas Capital goes on all 17 SMU uniforms, and SMU starts the state''s first Division I men''s lacrosse program.','3 min read',false,'general',25),
  ('smu-fb-avail-1021','video','insider','Football · Practice week','SMU Football: Alexander Kilgore and Jalen Hale, media availability','Mid-week before Cal (Oct. 21), in their own words.','7:52',true,'football',26),
  ('smu-wbb-tipoff','video','insider','Women''s Basketball · ACC Tipoff','SMU Women''s Basketball: Zahra King and Theresa Hagans Jr. at ACC Tipoff','Two Mustangs, live at the ACC''s preseason media event.','2:06',false,'womens-basketball',27),
  ('visit-weekend','article','recruiting','Recruiting','Visit Weekend: 48 hours on the Hilltop','Steak dinner in Uptown, a Saturday on the Boulevard and a very quiet Sunday brunch.','6 min read',false,null,28),
  ('recruiting-notebook','article','recruiting','Notebook','Recruiting notebook: a Friday night in Dallas ISD','Three stadiums, two staff cars and one sophomore everybody is about to know.','5 min read',false,null,29),
  ('board-2028','article','recruiting','Big Board','The 2028 board, as of late October','Where the (fictional) top targets stand, and which ones are coming back for an official visit.','7 min read',false,null,30),
  ('building-roster','article','portal','Portal','Building the Roster: the whiteboard in the war room','Pencil, never marker. Inside the meeting where portal targets get ranked, priced and argued about.','9 min read',false,null,31),
  ('portal-primer','article','portal','Portal','Portal season, explained without the jargon','The portal is just a database. Here''s what happens between a name going in and a player arriving for spring ball.','6 min read',false,null,32),
  ('film-pressure','article','film','Sample · Film Room','Film Room: the third-down pressure that keeps working','Two linebackers show blitz, one drops, and the quarterback throws into a safety who never moved. (Fictional sample.)','6 min read',true,null,33),
  ('film-screen','article','film','Sample · Film Room','Film Room: why the slot screen sets up everything','Four yards, then six, then 41. A fictional breakdown of how one cheap play gets a defense out of position.','5 min read',true,null,34),
  ('smu-vb-pitt-highlights','video','film','Film Room · Official highlights','SMU Volleyball: Highlights at Pittsburgh','Oct. 7: SMU wins 3-1 at No. 2 Pitt and ends the nation''s longest home winning streak.','6:52',false,'volleyball',35),
  ('film-session-redzone','video','film','Sample · Film Session','Film Session: red zone, frame by frame','A former linebacker on the telestrator for 20 minutes of goal-line snaps. (Fictional sample.)','20:05',true,null,36),
